import{X as e,Y as t,lt as n,n as r}from"./chunks/framework.DAfRfOCC.js";var i=JSON.parse(`{"title":"Chart types reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chart-types.md","filePath":"guide/chart-types.md"}`),a={name:`guide/chart-types.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="chart-types-reference" tabindex="-1">Chart types reference <a class="header-anchor" href="#chart-types-reference" aria-label="Permalink to “Chart types reference”">​</a></h1><p>How to build each chart type. They are all the same kind of thing: axes, one or several renderers, sometimes a transform that derives a series, sometimes annotations. The <a href="../examples/gallery">gallery</a> shows each of them, with its source.</p><table tabindex="0"><thead><tr><th>Chart type</th><th>How</th></tr></thead><tbody><tr><td>Line, area, scatter</td><td><code>D3PLineRenderer</code>, <code>D3PAreaRenderer</code>, <code>D3PScatterRenderer</code></td></tr><tr><td>Spline, step</td><td><code>style.curve</code>: <code>monotone</code>, <code>step</code>, <code>stepBefore</code>, <code>stepAfter</code>, <code>basis</code>, <code>cardinal</code>, <code>catmullRom</code>, <code>natural</code></td></tr><tr><td>Gaps in the data</td><td><code>style.gaps: &#39;break&#39;</code> (default <code>connect</code>)</td></tr><tr><td>Columns</td><td><code>D3PBarRenderer</code> on a band axis; <code>count</code> and <code>index</code> group several series side by side</td></tr><tr><td>Horizontal bars</td><td><code>D3PBarRenderer</code> with <code>orientation: &#39;horizontal&#39;</code>, categories on a band axis at the left</td></tr><tr><td>Stacked, 100 %, streamgraph</td><td><code>D3PStack</code> with <code>offset: &#39;none&#39; | &#39;expand&#39; | &#39;silhouette&#39; | &#39;wiggle&#39;</code> (and <code>order</code>), drawn by areas or bars</td></tr><tr><td>Range area</td><td>a series with <code>columns: [&#39;x&#39;, &#39;high&#39;, &#39;low&#39;]</code> and <code>D3PAreaRenderer({ props: { base: &#39;low&#39; } })</code></td></tr><tr><td>Range column, timeline</td><td><code>D3PBarRenderer</code> with <code>base: &#39;start&#39;</code> (and <code>orientation: &#39;horizontal&#39;</code> for a timeline)</td></tr><tr><td>Histogram</td><td><code>D3PHistogram</code> (or <code>d3pHistogram</code>) feeding <code>D3PBarRenderer</code>: bars take their width from the bin edges</td></tr><tr><td>Waterfall</td><td><code>D3PWaterfall</code> feeding <code>D3PBarRenderer</code> with <code>style.colorBy: &#39;kind&#39;</code></td></tr><tr><td>Lollipop</td><td><code>D3PBarRenderer</code> with <code>style.shape: &#39;lollipop&#39;</code></td></tr><tr><td>Candlestick</td><td><code>D3PCandlestickRenderer</code> on a series with <code>open</code>, <code>high</code>, <code>low</code>, <code>close</code></td></tr><tr><td>Box plot</td><td><code>D3PBoxPlotRenderer</code>; <code>d3pBoxPlotRows(groups)</code> computes quartiles, whiskers and outliers from raw samples</td></tr><tr><td>Dumbbell</td><td><code>D3PDumbbellRenderer</code> on a series with <code>start</code> and <code>end</code></td></tr><tr><td>Bubble</td><td><code>D3PBubbleRenderer</code> on a series with a <code>size</code> column</td></tr><tr><td>Heatmap</td><td><code>D3PHeatmapRenderer</code> with a <code>D3PColorScale</code>, and a <code>D3PColorLegend</code></td></tr><tr><td>Pie, donut, semi-donut</td><td><code>D3PPieRenderer</code> in a <code>D3PPolarSystem</code> (<code>innerRadius</code>, <code>sweep</code>)</td></tr><tr><td>Radar</td><td>polar axes with <code>D3PRadarAngleAxisRenderer</code>, and lines or areas with <code>curve: &#39;straight&#39;</code> and <code>closed: true</code></td></tr><tr><td>Polar area (rose)</td><td><code>D3PBarRenderer</code> on polar axes, categories on the angle</td></tr><tr><td>Radial bar, gauge</td><td><code>D3PBarRenderer</code> with <code>orientation: &#39;horizontal&#39;</code> on polar axes, categories on the radius; <code>sweep: 180</code> for a gauge</td></tr><tr><td>Funnel</td><td><code>D3PFunnelRenderer</code> (no axes)</td></tr><tr><td>Slope</td><td>lines on a point axis with a blank category at each end</td></tr><tr><td>Sparkline</td><td><code>d3pSparkline({ container, data, type })</code></td></tr><tr><td>Annotations</td><td><code>D3PAnnotationLine</code>, <code>D3PAnnotationBand</code>, <code>D3PAnnotationPoint</code>, <code>D3PAnnotationText</code></td></tr></tbody></table><p>Not included: treemap, sunburst and icicle (they need hierarchical data), violin and raincloud, waffle, unit and beeswarm, and the multi-chart features (trellis, crossfilter, linked selections).</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to “Data”">​</a></h2><p>A series is a list of points; a point is <code>[x, value, ...others]</code>. The columns have names, and a renderer asks for the ones it needs:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// two columns, as always</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PSeries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cpu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, data: [[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// several columns: a candlestick needs open, high, low and close</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> D3PSeries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;AAPL&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  columns: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;open&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;high&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;low&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;close&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  primary: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;close&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// what a single value means (tooltip marker, legend, default domain)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  data: rows,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p><code>primary</code> defaults to the second column. A renderer that needs columns the series lacks refuses it when attached, and says which ones.</p><p>Accepted inputs, detected on the first row:</p><table tabindex="0"><thead><tr><th>Input</th><th>Example</th></tr></thead><tbody><tr><td>numbers, typed arrays</td><td><code>[3, 5, 2]</code>: <code>x</code> is the index (two columns only)</td></tr><tr><td>positional rows</td><td><code>[[0, 3], [&#39;a&#39;, 5]]</code>, in the order of <code>columns</code></td></tr><tr><td>object rows</td><td><code>[{ x: 0, y: 3 }]</code>, or other keys and functions with <code>fields: { x: &#39;t&#39;, y: (row) =&gt; row.v }</code></td></tr><tr><td>column-oriented</td><td><code>{ x: [0, 1], y: [3, 5] }</code></td></tr><tr><td>any iterable of those</td><td>a <code>Set</code>, a generator, <code>Map.entries()</code></td></tr></tbody></table><h3 id="fitting-the-domains" tabindex="-1">Fitting the domains <a class="header-anchor" href="#fitting-the-domains" aria-label="Permalink to “Fitting the domains”">​</a></h3><p><code>D3PAutoDomain.linkSeries(series, [dx, dy])</code> fits the second domain to <strong>every value column</strong> (a candlestick&#39;s lows and highs, not only its close). Columns that are not positions (<code>size</code>, <code>value</code>, <code>kind</code>, <code>color</code>, <code>label</code>) are left out; <code>domainColumns</code> overrides this. To map columns one by one, use names: <code>linkSeries(series, { x: dx, value: colors.domain })</code>.</p><h3 id="derived-series" tabindex="-1">Derived series <a class="header-anchor" href="#derived-series" aria-label="Permalink to “Derived series”">​</a></h3><p>A transform derives series from other series and keeps them up to date. The derived series are ordinary series that carry extra columns for the renderers:</p><table tabindex="0"><thead><tr><th>Transform</th><th>Derived columns</th></tr></thead><tbody><tr><td><code>D3PStack</code></td><td><code>x</code>, <code>y</code> (top of the layer), <code>y0</code> (its base), <code>value</code> (the original value, which the tooltip shows)</td></tr><tr><td><code>D3PWaterfall</code></td><td><code>x</code>, <code>y</code>, <code>y0</code>, <code>value</code>, <code>kind</code> (<code>up</code>, <code>down</code>, <code>total</code>)</td></tr><tr><td><code>D3PHistogram</code></td><td><code>x</code>, <code>y</code> (count), <code>x0</code>, <code>x1</code> (the edges of the bin)</td></tr></tbody></table><p>Areas and bars read a <code>y0</code> column by themselves, or the one named by <code>base</code>.</p><h2 id="coordinate-systems" tabindex="-1">Coordinate systems <a class="header-anchor" href="#coordinate-systems" aria-label="Permalink to “Coordinate systems”">​</a></h2><p>Bars, areas, lines, scatter, bubbles and heatmaps draw in <strong>any</strong> coordinate system: rectangles in a cartesian one, arcs in a polar one, so the same renderer gives a column chart or a polar area. Candlesticks, box plots and dumbbells draw rectangles and lines and are cartesian only; pies are polar only; funnels use no system. A renderer that does not support a system says so.</p><p>A <a href="../guide/concepts#coordinate-systems">polar system</a> can cover part of a circle (<code>sweep</code>), be a ring (<code>innerRadius</code>), start anywhere (<code>startAngle</code>) and be moved (<code>shift</code>, as fractions of the radius, to center a half disc).</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};